--- a/lib/settings.js
+++ b/lib/settings.js
@@ -1,7 +1,22 @@
 const path = require('path');

+// Freeze every level, so nested config values are protected too.
+function deepFreeze(value) {
+  if (value && typeof value === 'object') {
+    Object.values(value).forEach(deepFreeze);
+    Object.freeze(value);
+  }
+  return value;
+}
+
+// Loaded once and frozen: nothing may mutate the shared config in place.
+const DEFAULTS = deepFreeze(
+  require(path.join(__dirname, '..', 'config', 'defaults.json'))
+);
+
+// Always return a fresh copy so callers can merge into it safely.
 function getDefaults() {
-  return require(path.join(__dirname, '..', 'config', 'defaults.json'));
+  return structuredClone(DEFAULTS);
 }

 module.exports = { getDefaults };
